// KALYPSO site: the live window, downloads from the latest release, and small touches.
// Everything works without the GitHub API; it only fills in real files and stars when it can.

const REPO = "kalyppso/kalypso";
document.documentElement.classList.add("js");
const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

/* ---------- The live window ---------- */

// Click around: each sidebar item shows its panel.
$$(".ws-nav button").forEach((b) =>
  b.addEventListener("click", () => {
    $$(".ws-nav button").forEach((x) => x.classList.toggle("on", x === b));
    $$(".panel").forEach((p) => p.classList.toggle("on", p.dataset.panel === b.dataset.panel));
  }),
);

// The shape of a real run, as the Claude Agent SDK runtime writes it to the transcript.
const DEMO = [
  ["status", "started · claude-sonnet-5-5 · 22 tools", 500],
  ["text", "I'll run the tests first to see what fails.", 900],
  ["tool", "Bash|npm test", 700, 0.012],
  ["output", "23 passing, 1 failing: parses an empty config file", 900],
  ["tool", "Read|src/config.ts", 600, 0.018],
  ["tool", "Edit|src/config.ts", 900, 0.027],
  ["tool", "Bash|npm test", 700, 0.012],
  ["output", "24 passing", 900],
  ["tool", "Bash|git push --force origin main", 800, 0.009],
  ["policy", 'Blocked by policy <b>"No force-push to main"</b>. The command never ran.', 1500, 0, true],
  ["text", "Force-pushing to main isn't allowed here. I'll push a branch and open a pull request instead.", 1000, 0.015],
  ["tool", "Bash|git push origin fix/empty-config", 800, 0.009],
  ["tool", "Bash|gh pr create --fill", 900, 0.012],
  ["output", "https://github.com/acme/app/pull/482", 700],
  ["result", "Done · 9 turns · $0.042", 4500],
];

(function demo() {
  const log = $("#demo-log");
  if (!log) return;
  const status = $("#demo-status");
  const esc = (t) => t.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  let i = 0, spend = 0.84, blocked = 0, timer = null, visible = false;
  const meters = () => {
    $("#demo-spend").textContent = `$${spend.toFixed(2)}`;
    $("#demo-meter").style.width = `${Math.min(100, (spend / 5) * 100)}%`;
    $("#demo-blocked-row").textContent = `${blocked} today`;
  };
  const line = ([kind, text], animate = true) => {
    const li = document.createElement("li");
    li.className = `k-${kind}${animate ? " new" : ""}`;
    if (kind === "tool") { const [tool, arg] = text.split("|"); li.innerHTML = `<b>${tool}</b>${esc(arg)}`; }
    else if (kind === "policy") li.innerHTML = text;
    else li.textContent = text;
    log.append(li);
    while (log.children.length > 24) log.firstElementChild.remove();
  };
  const apply = (s) => {
    spend += s[3] || 0;
    if (s[4]) blocked += 1;
    if (s[0] === "result") { status.classList.add("done"); status.lastChild.textContent = "Waiting for a message"; }
    meters();
  };
  const reset = () => {
    log.replaceChildren(); i = 0; spend = 0.84; blocked = 0;
    status.classList.remove("done"); status.lastChild.textContent = "Running"; meters();
  };
  const step = () => {
    timer = null;
    if (!visible) return;
    if (i >= DEMO.length) { reset(); timer = setTimeout(step, 600); return; }
    const s = DEMO[i++];
    line(s); apply(s);
    timer = setTimeout(step, s[2]);
  };
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
    DEMO.forEach((s) => { line(s, false); apply(s); });
    return;
  }
  meters();
  new IntersectionObserver(([e]) => {
    visible = e.isIntersecting;
    if (visible && !timer) timer = setTimeout(step, 400);
  }).observe($(".stage"));
})();

/* ---------- Downloads ---------- */

const PICK = {
  exe: (n) => /\.exe$/i.test(n),
  msi: (n) => /\.msi$/i.test(n),
  dmg: (n) => /\.dmg$/i.test(n),
  appimage: (n) => /\.appimage$/i.test(n),
  deb: (n) => /\.deb$/i.test(n),
  rpm: (n) => /\.rpm$/i.test(n),
};
const MAIN = { windows: "exe", mac: "dmg", linux: "appimage" };
const NAME = { windows: "Windows", mac: "macOS", linux: "Linux" };
const macArch = (name) => (/universal/i.test(name) ? "Apple silicon and Intel" : /aarch64|arm64/i.test(name) ? "Apple silicon" : /x64|x86_64/i.test(name) ? "Intel" : "");

function platform() {
  const ua = navigator.userAgent;
  if (/Windows/i.test(ua)) return "windows";
  if (/Macintosh|Mac OS X/i.test(ua) && !/iPhone|iPad/i.test(ua)) return "mac";
  if (/Linux/i.test(ua) && !/Android/i.test(ua)) return "linux";
  return null;
}

async function latestRelease() {
  const res = await fetch(`https://api.github.com/repos/${REPO}/releases?per_page=10`, { headers: { Accept: "application/vnd.github+json" } });
  if (!res.ok) throw new Error(String(res.status));
  const all = (await res.json()).filter((r) => !r.draft && r.assets.length);
  // Release candidates are for testing: offer the latest full release, a pre-release only if there is nothing else.
  return all.find((r) => !r.prerelease) ?? all[0] ?? null;
}

(async () => {
  const os = platform();
  if (os) {
    $(`.oses li[data-os="${os}"]`)?.classList.add("mine");
    $("#hero-label").textContent = `Download for ${NAME[os]}`;
  }
  let release = null;
  try { release = await latestRelease(); } catch { /* offline or rate-limited: links stay on the releases page */ }
  if (!release) return;
  for (const a of $$(".oses a[data-asset]")) {
    const asset = release.assets.find((x) => PICK[a.dataset.asset](x.name));
    if (asset) { a.href = asset.browser_download_url; a.title = asset.name; } else a.hidden = true;
  }
  const dmg = release.assets.find((x) => PICK.dmg(x.name));
  if (dmg && macArch(dmg.name)) $("#mac-arch").textContent = macArch(dmg.name);
  const mine = os && release.assets.find((x) => PICK[MAIN[os]](x.name));
  if (mine) {
    $("#hero-download").href = mine.browser_download_url;
    $$("[data-dl]").forEach((a) => (a.href = mine.browser_download_url));
  }
  const when = new Date(release.published_at).toLocaleDateString(undefined, { month: "long", day: "numeric", year: "numeric" });
  $("#release-line").textContent = `${release.tag_name}, ${when}. No account, no telemetry. Needs Docker or Podman.`;
})();

// Stars: shown only once the number means something.
fetch(`https://api.github.com/repos/${REPO}`)
  .then((r) => (r.ok ? r.json() : null))
  .then((repo) => {
    if (!repo || !(repo.stargazers_count >= 50)) return;
    $$("[data-stars]").forEach((el) => { el.textContent = repo.stargazers_count.toLocaleString(); el.hidden = false; });
  })
  .catch(() => {});

/* ---------- Page chrome ---------- */

const sentinel = document.createElement("div");
sentinel.style.cssText = "position:absolute;top:0;height:1px;width:1px";
document.body.prepend(sentinel);
new IntersectionObserver(([e]) => $(".nav").classList.toggle("scrolled", !e.isIntersecting)).observe(sentinel);

const io = new IntersectionObserver(
  (entries) => {
    for (const e of entries) if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
  },
  { rootMargin: "0px 0px -10% 0px" },
);
$$(".three, .get, .faq").forEach((el) => { el.classList.add("reveal"); io.observe(el); });

/* ---------- The section you're in ---------- */

(function navActive() {
  const links = $$('.nav-link[href^="#"]');
  const targets = links.map((a) => $(a.getAttribute("href"))).filter(Boolean);
  if (!targets.length) return;
  // The section crossing the upper middle of the screen is the one you're in.
  const watch = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue;
        links.forEach((a) => a.classList.toggle("on", a.getAttribute("href") === `#${e.target.id}`));
      }
    },
    { rootMargin: "-40% 0px -55% 0px" },
  );
  targets.forEach((t) => watch.observe(t));
})();

/* ---------- The layers: point at one ---------- */

(function isle() {
  const box = $(".isle");
  if (!box) return;
  const map = $("#isle", box);
  const note = $("#isle-note", box);
  const SAY = {
    sandbox: "Sandbox: the agent runs in its own box and only reaches hosts you allowed.",
    policies: "Policies: every tool call is checked against your rules. Risky ones wait for you.",
    vault: "Vault: the stand-in key is swapped for the real one here, never inside the sandbox.",
    gateway: "Gateway: every model call is metered and stops at the budget you set.",
  };
  const IDLE = note.textContent;
  // Point at a layer: it lights up and the note says what it does.
  const pick = (key) => {
    if (key) box.dataset.on = key; else delete box.dataset.on;
    note.textContent = key ? SAY[key] : IDLE;
    note.classList.toggle("on", !!key);
  };
  const layerOf = (e) => e.target.closest("[data-layer]")?.dataset.layer || null;
  map.addEventListener("mouseover", (e) => pick(layerOf(e)));
  map.addEventListener("mouseleave", () => pick(null));
  map.addEventListener("focusin", (e) => pick(layerOf(e)));
  map.addEventListener("focusout", () => pick(null));
  map.addEventListener("click", (e) => pick(layerOf(e))); // touch
  // The calls only move while the map is on screen, and never with reduced motion.
  if (reduce) { map.pauseAnimations(); return; }
  new IntersectionObserver(([e]) => (e.isIntersecting ? map.unpauseAnimations() : map.pauseAnimations())).observe(map);
})();

/* ---------- Kalypso, drawn in code ----------
   She is a set of polylines traced once from the logo (the centreline of every stroke),
   stroked on a canvas as clean vector lines. Her head is modelled as a rough ellipsoid, so
   she turns toward the cursor in 3D; lines near the cursor bend away from it. She is drawn
   in from the bottom on load, and a scanline passes over her now and then. */

(function kalypso() {
  const fig = $(".portrait");
  const cv = $("#kalypso");
  if (!fig || !cv) return;
  const K = {"w":790,"h":1090,"lines":"","eyes":[[518,512],[635,513]],"stars":[[110,413],[195,452],[96,457],[77,864],[186,787],[700,869],[528,957],[243,982],[387,1064],[387,865]],"head":{"cx":510,"cy":450,"rx":250,"ry":330},"nodes":[[615,115],[582,118],[614,144],[494,130],[540,174],[156,174],[144,184],[490,179],[469,187],[487,195],[358,242],[382,244],[156,251],[385,258],[343,269],[368,266],[238,279],[196,301],[372,281],[356,289],[222,309],[598,306],[122,306],[145,319],[128,331],[591,372],[661,378],[534,363],[113,353],[209,334],[86,368],[211,381],[487,384],[183,401],[472,411],[634,455],[111,414],[241,436],[160,460],[195,452],[437,466],[222,485],[676,459],[163,463],[139,506],[423,509],[307,504],[148,489],[573,512],[555,514],[391,505],[332,519],[589,507],[590,523],[655,533],[622,598],[556,538],[199,519],[642,533],[212,568],[655,551],[342,586],[636,607],[345,604],[607,614],[490,613],[624,614],[492,681],[427,738],[561,740],[318,724],[303,791],[366,770],[444,779],[409,761],[487,774],[185,790],[595,787],[241,786],[427,803],[496,797],[276,780],[534,784],[538,812],[452,803],[604,831],[86,860],[178,828],[290,815],[545,817],[443,829],[412,839],[238,824],[466,840],[584,849],[384,883],[320,847],[310,878],[346,834],[333,850],[607,865],[452,869],[279,844],[270,896],[485,860],[325,880],[524,885],[559,875],[401,888],[351,893],[478,876],[122,898],[609,897],[140,890],[599,948],[573,908],[459,909],[537,916],[334,907],[382,888],[266,900],[236,896],[247,940],[214,934],[360,950],[451,916],[451,980],[246,979],[331,995],[179,989],[358,977]]};
  const ctx = cv.getContext("2d");
  const fine = matchMedia("(pointer: fine)").matches;
  // She is drawn in the theme's ink: near-white on the dark theme, near-black on the white one.
  let ink = "236,236,240";
  const readInk = () => { ink = getComputedStyle(document.documentElement).getPropertyValue("--ink").trim().split(/\s+/).join(","); };
  readInk();
  addEventListener("themechange", () => { readInk(); if (reduce) draw(performance.now()); });

  // Unpack: per polyline, a count, the first point (uint16 x, y), then int8 steps.
  const raw = Uint8Array.from(atob(K.lines), (c) => c.charCodeAt(0));
  const dv = new DataView(raw.buffer);
  const xs = [], ys = [], starts = [];
  for (let o = 0; o < raw.length;) {
    const n = dv.getUint16(o, true); let x = dv.getUint16(o + 2, true), y = dv.getUint16(o + 4, true); o += 6;
    starts.push(xs.length); xs.push(x); ys.push(y);
    for (let k = 1; k < n; k++, o += 2) { x += dv.getInt8(o); y += dv.getInt8(o + 1); xs.push(x); ys.push(y); }
  }
  starts.push(xs.length);
  const nv = xs.length, hd = K.head, cx0 = K.w / 2, cy0 = K.h / 2;
  const depth = (x, y) => { const dx = (x - hd.cx) / hd.rx, dy = (y - hd.cy) / hd.ry, q = 1 - dx * dx - dy * dy; return q > 0 ? Math.sqrt(q) * hd.rx * 0.55 : 0; };
  const PX = Float32Array.from(xs, (x) => x - cx0), PY = Float32Array.from(ys, (y) => y - cy0);
  const PZ = Float32Array.from(xs, (x, i) => depth(x, ys[i]));
  const QX = new Float32Array(nv), QY = new Float32Array(nv);

  let W = 0, H = 0, dpr = 1, s = 1;
  let rx = 0, ry = 0, tx = 0, ty = 0; // turn, -1..1
  let mx = -1e5, my = -1e5; // cursor, in CSS pixels on the canvas
  let t0 = 0, raf = null, visible = true, last = 0;

  const size = () => {
    dpr = Math.min(2, devicePixelRatio || 1);
    W = fig.clientWidth;
    H = W * (K.h / K.w);
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
    cv.style.height = H + "px";
    s = W / K.w;
  };

  const place = (x, y, z, cyr, syr, cxr, sxr) => {
    const X = x * cyr + z * syr, Z1 = -x * syr + z * cyr;
    return [(X + cx0) * s, (y * cxr - Z1 * sxr + cy0) * s];
  };

  const draw = (now) => {
    const t = now - t0;
    const ay = rx * 0.3, ax = -ry * 0.18;
    const cyr = Math.cos(ay), syr = Math.sin(ay), cxr = Math.cos(ax), sxr = Math.sin(ax);
    const R = 60, R2 = R * R, PUSH = 14;
    for (let i = 0; i < nv; i++) {
      const x = PX[i], y = PY[i], z = PZ[i];
      const X = x * cyr + z * syr, Z1 = -x * syr + z * cyr;
      let px = (X + cx0) * s, py = (y * cxr - Z1 * sxr + cy0) * s;
      const dx = px - mx, dy = py - my, d2 = dx * dx + dy * dy;
      if (d2 < R2) { const d = Math.sqrt(d2) || 1, f = (1 - d / R); const p = f * f * PUSH; px += (dx / d) * p; py += (dy / d) * p; }
      QX[i] = px; QY[i] = py;
    }
    const path = new Path2D();
    for (let k = 0; k < starts.length - 1; k++) {
      const a = starts[k], b = starts[k + 1];
      path.moveTo(QX[a], QY[a]);
      for (let i = a + 1; i < b; i++) path.lineTo(QX[i], QY[i]);
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    ctx.lineJoin = ctx.lineCap = "round";
    // Drawn in from the bottom: everything below the rising edge, and the edge itself lit.
    const rise = reduce ? 1 : Math.min(1, t / 1700);
    const edge = H * (1 - (1 - (1 - rise) ** 3));
    ctx.save();
    ctx.beginPath(); ctx.rect(0, edge, W, H - edge); ctx.clip();
    ctx.lineWidth = 0.75;
    ctx.strokeStyle = `rgba(${ink},0.82)`;
    ctx.stroke(path);
    ctx.restore();
    const lit = (y0, h, a) => {
      ctx.save(); ctx.beginPath(); ctx.rect(0, y0, W, h); ctx.clip();
      ctx.lineWidth = 1.1; ctx.strokeStyle = `rgba(${ink},${a})`; ctx.stroke(path); ctx.restore();
    };
    if (rise < 1) { lit(edge, 10, 1); return; }
    // A scanline every 8 seconds.
    const scan = reduce ? -1 : ((t - 2600) % 8000) / 1700;
    if (scan >= 0 && scan <= 1) lit(scan * H - 9, 18, 0.9);
  };

  const loop = (now) => {
    raf = null;
    if (!visible) return;
    rx += (tx - rx) * 0.08;
    ry += (ty - ry) * 0.08;
    if (now - last > (fine ? 16 : 33)) { draw(now); last = now; }
    raf = requestAnimationFrame(loop);
  };
  const start = () => { if (!raf && !reduce) raf = requestAnimationFrame(loop); };

  if (fine && !reduce) {
    addEventListener("pointermove", (e) => {
      const b = cv.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, (e.clientX - (b.left + b.width / 2)) / (innerWidth / 2)));
      ty = Math.max(-1, Math.min(1, (e.clientY - (b.top + b.height * 0.42)) / (innerHeight / 2)));
      mx = e.clientX - b.left;
      my = e.clientY - b.top;
    }, { passive: true });
    document.documentElement.addEventListener("pointerleave", () => { tx = ty = 0; mx = my = -1e5; });
  }
  new ResizeObserver(() => { size(); if (reduce) draw(performance.now()); }).observe(fig);
  new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible) start(); }).observe(cv);
  size();
  t0 = performance.now();
  if (reduce) draw(t0); else start();
})();

/* ---------- In the app: tabs over real screens ---------- */

(function showcase() {
  const tabs = $$(".show-tabs [role=tab]");
  if (!tabs.length) return;
  const row = $(".show-tabs");
  const panel = $("#show-panel");
  // Tabs advance on their own every few seconds, only while the section is well in view and
  // you aren't pointing at it; picking one jumps there and the timer starts over.
  const select = (i, focus = false) => {
    const current = (i + tabs.length) % tabs.length;
    const key = tabs[current].dataset.tab;
    tabs.forEach((t, n) => {
      t.setAttribute("aria-selected", String(n === current));
      t.tabIndex = n === current ? 0 : -1;
    });
    $$(".show-shot, .show-copy").forEach((el) => el.classList.toggle("on", el.dataset.tab === key));
    panel.setAttribute("aria-labelledby", tabs[current].id);
    if (focus) tabs[current].focus({ preventScroll: true });
    // Keep the chosen tab visible in its own row (phones), without moving the page.
    const t = tabs[current];
    if (t.offsetLeft < row.scrollLeft || t.offsetLeft + t.offsetWidth > row.scrollLeft + row.clientWidth)
      row.scrollTo({ left: t.offsetLeft - 8, behavior: reduce ? "auto" : "smooth" });
  };
  tabs.forEach((t, i) => t.addEventListener("click", () => select(i)));
  row.addEventListener("keydown", (e) => {
    const now = tabs.findIndex((t) => t.getAttribute("aria-selected") === "true");
    const go = { ArrowRight: now + 1, ArrowLeft: now - 1, Home: 0, End: tabs.length - 1 }[e.key];
    if (go === undefined) return;
    e.preventDefault();
    select(go, true);
  });
  select(0);

  // Scrolling moves through the tabs: the section stays pinned while you scroll, and each
  // stretch of scrolling selects the next tab. One marker per tab covers its stretch.
  const pin = $(".show-pin");
  if (pin && !reduce) {
    const marks = tabs.map((t, k) => {
      const m = document.createElement("i");
      m.className = "show-mark";
      m.style.top = `${(k / tabs.length) * 100}%`;
      m.style.height = `${100 / tabs.length}%`;
      pin.append(m);
      new IntersectionObserver(([e]) => { if (e.isIntersecting) select(k); }, { rootMargin: "-50% 0px -50% 0px" }).observe(m);
      return m;
    });
    // The bar on each tab fills as you scroll through its stretch.
    const steps = Array.from({ length: 21 }, (_, i) => i / 20);
    marks.forEach((m, k) => new IntersectionObserver(([e]) => {
      const r = e.boundingClientRect, mid = innerHeight / 2;
      tabs[k].style.setProperty("--p", Math.min(1, Math.max(0, (mid - r.top) / r.height)).toFixed(3));
    }, { threshold: steps }).observe(m));
    // A click scrolls to that tab's stretch, so scrolling and clicking agree.
    tabs.forEach((t, k) => t.addEventListener("click", () => {
      const top = marks[k].getBoundingClientRect().top + scrollY - innerHeight / 2 + 8;
      scrollTo({ top, behavior: "smooth" });
    }));
  } else {
    tabs.forEach((t) => t.style.setProperty("--p", "1"));
  }

  // The screen settles flat once it's well in view.
  const show = $(".show");
  new IntersectionObserver(([e], io) => { if (e.isIntersecting) { show.classList.add("in"); io.disconnect(); } }, { threshold: 0.3 }).observe(show);
})();

/* ---------- Theme: dark or white ---------- */

(function theme() {
  const btn = $("#theme");
  if (!btn) return;
  const root = document.documentElement;
  const label = () => btn.setAttribute("aria-label", root.dataset.theme === "light" ? "Switch to the dark theme" : "Switch to the white theme");
  const set = (t, save) => {
    root.dataset.theme = t;
    if (save) try { localStorage.setItem("theme", t); } catch (e) {}
    label();
    dispatchEvent(new Event("themechange"));
  };
  label();
  btn.addEventListener("click", () => set(root.dataset.theme === "light" ? "dark" : "light", true));
  // Until you pick one, follow the system.
  matchMedia("(prefers-color-scheme: light)").addEventListener("change", (e) => {
    let saved = null;
    try { saved = localStorage.getItem("theme"); } catch (err) {}
    if (!saved) set(e.matches ? "light" : "dark", false);
  });
})();

/* The footer wordmark's gradient sweep (SMIL) holds still with reduced motion. */
if (reduce) document.querySelector(".wordmark")?.pauseAnimations?.();

/* ---------- Scroll: arrivals and scroll-linked moments, without scroll listeners ---------- */
(function scrollMotion() {
  if (reduce) return;
  // One-shot arrivals: headlines come into focus, grids stagger in.
  const arrive = new IntersectionObserver((entries) => {
    for (const e of entries) if (e.isIntersecting) { e.target.classList.add("in"); arrive.unobserve(e.target); }
  }, { rootMargin: "0px 0px -12% 0px" });
  $$("main h2").forEach((h) => arrive.observe(h));
  $$(".three, .uses-grid, .logos").forEach((g) => {
    g.classList.add("stagger");
    [...g.children].forEach((c, i) => c.style.setProperty("--i", i));
    arrive.observe(g);
  });
  // Scroll-linked: how far an element has come into view (0..1), from IntersectionObserver ratios.
  const steps = Array.from({ length: 41 }, (_, i) => i / 40);
  const track = (el, fn) => new IntersectionObserver(([e]) => fn(e), { threshold: steps }).observe(el);
  // Where an element sits in the viewport: 0 entering at the bottom, 1 leaving at the top.
  const pos = (e) => { const r = e.boundingClientRect, h = e.rootBounds?.height || innerHeight; return Math.min(1, Math.max(0, (h - r.top) / (h + r.height))); };
  const shot = $(".ask-shot");
  if (shot) track(shot, (e) => shot.style.setProperty("--tilt", Math.max(0, 1 - e.intersectionRatio * 1.6).toFixed(3)));
  $$(".use-img").forEach((el) => track(el, (e) => el.style.setProperty("--py", pos(e).toFixed(3))));
  const sign = $(".foot-sign");
  if (sign) track(sign, (e) => sign.style.setProperty("--open", Math.min(1, e.intersectionRatio * 1.4).toFixed(3)));
})();

/* ---------- Mythic halftones: paintings from the Odyssey, redrawn as dots ---------- */
(function halftones() {
  const cards = $$("canvas[data-dots]");
  if (!cards.length) return;
  let rgb = [236, 236, 240], light = false;
  const g = () => getComputedStyle(document.documentElement);
  const hex = (h) => { h = h.trim().replace("#", ""); return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)); };
  let grad = [];
  const read = () => {
    rgb = g().getPropertyValue("--ink").trim().split(/\s+/).map(Number);
    light = document.documentElement.dataset.theme === "light";
    grad = ["--g1", "--g2", "--g3", "--g4"].map((v) => hex(g().getPropertyValue(v)));
  };
  read();
  const mix = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
  // Ink near the bottom-left, a hint of the gradient toward the top-right.
  const tint = (u, v) => { const k = Math.min(1, Math.max(0, (u + (1 - v)) / 2)); return mix(rgb, grad[1], 0.35 * k); };

  for (const cv of cards) {
    const ctx = cv.getContext("2d");
    const img = new Image();
    let lum = null, lw = 0, lh = 0, mx = -1, my = -1, raf = 0, wave = 0;
    img.onload = () => {
      const o = document.createElement("canvas"); lw = o.width = img.naturalWidth; lh = o.height = img.naturalHeight;
      const c = o.getContext("2d"); c.drawImage(img, 0, 0);
      const d = c.getImageData(0, 0, lw, lh).data; lum = new Float32Array(lw * lh);
      for (let i = 0; i < lw * lh; i++) lum[i] = Math.pow(d[i * 4] / 255, 0.75);
      draw();
    };
    img.src = cv.dataset.dots;
    const draw = () => {
      raf = 0;
      if (!lum) return;
      const dpr = Math.min(2, devicePixelRatio || 1), W = cv.clientWidth, H = cv.clientHeight;
      if (!W || !H) return;
      if (cv.width !== Math.round(W * dpr)) { cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr); }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.clearRect(0, 0, W, H);
      const step = W < 500 ? 6 : 7, r0 = step * 0.52;
      // Cover-fit the painting into the card.
      const sc = Math.max(W / lw, H / lh), ox = (W - lw * sc) / 2, oy = (H - lh * sc) / 2;
      const py = parseFloat(cv.parentElement.style.getPropertyValue("--py") || "0.5");
      for (let y = step / 2; y < H; y += step) {
        for (let x = step / 2; x < W; x += step) {
          const sx = Math.min(lw - 1, Math.max(0, Math.floor((x - ox) / sc))), sy = Math.min(lh - 1, Math.max(0, Math.floor((y - oy) / sc)));
          // Light theme: dots are ink on paper, so they carry the painting's darkness.
          let l = light ? 1 - lum[sy * lw + sx] * 0.92 : lum[sy * lw + sx];
          // A slow light passes over the picture as you scroll; the cursor brightens what it touches.
          l *= 0.82 + 0.3 * Math.exp(-(((y / H) - (1.2 - py * 1.4)) ** 2) * 9);
          if (mx >= 0) { const d2 = (x - mx) ** 2 + (y - my) ** 2; l += 0.5 * Math.exp(-d2 / 2600); }
          // Every cell keeps a faint dot, so the grid reads as one surface; light grows it.
          const r = r0 * (light ? 0.14 + 0.86 * Math.min(1, l) ** 1.2 : 0.16 + 0.84 * Math.min(1, l) ** 1.15);
          const [cr, cg, cb] = tint(x / W, y / H);
          ctx.fillStyle = `rgba(${cr},${cg},${cb},${(light ? 0.14 + 0.8 * Math.min(1, l) ** 1.25 : 0.22 + 0.78 * Math.min(1, l)).toFixed(2)})`;
          ctx.beginPath(); ctx.arc(x, y, r, 0, 6.2832); ctx.fill();
        }
      }
    };
    const ask = () => { if (!raf) raf = requestAnimationFrame(draw); };
    new ResizeObserver(ask).observe(cv);
    new MutationObserver(ask).observe(cv.parentElement, { attributes: true, attributeFilter: ["style"] });
    if (!reduce) {
      cv.addEventListener("pointermove", (e) => { const b = cv.getBoundingClientRect(); mx = e.clientX - b.left; my = e.clientY - b.top; ask(); });
      cv.addEventListener("pointerleave", () => { mx = my = -1; ask(); });
    }
    addEventListener("themechange", () => { read(); ask(); });
  }
})();

/* The tour plays only on screen, and not at all with reduced motion (its first frame stays). */
(function tour() {
  const v = $(".ask-shot video");
  if (!v) return;
  if (reduce) { v.removeAttribute("autoplay"); v.pause(); v.controls = true; return; }
  new IntersectionObserver(([e]) => (e.isIntersecting ? v.play().catch(() => {}) : v.pause()), { threshold: 0.25 }).observe(v);
})();

/* ---------- The chat orb from the app: a ring of bars around an egg-shaped body ---------- */
// makeOrb(canvas, size) draws it and returns controls: beat() for a keystroke, kick() for a
// wave round the ring, active(on) to wake it.
function makeOrb(el, size) {
  const ctx = el.getContext("2d");
  const dpr = Math.min(devicePixelRatio || 1, 2);
  el.width = el.height = Math.round(size * dpr);
  el.style.width = el.style.height = size + "px";
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const bars = 72, c = size / 2, core = size * 0.24, base = size * 0.31, reach = size * 0.17, width = Math.max(1.25, size * 0.016);
  let energy = 0, spin = 0, wave = 0, waveAt = 0, level = 0, beats = 0, kick = 0, on = false, rgb = "236,236,240";
  const heights = new Float32Array(bars), jolt = new Float32Array(bars);
  const readColour = () => { const m = /rgba?\(([^)]+)\)/.exec(getComputedStyle(el).color); if (m) rgb = m[1].split(",").slice(0, 3).join(","); };
  readColour(); addEventListener("themechange", readColour);
  const rgba = (a) => `rgba(${rgb},${a.toFixed(3)})`;
  let last = performance.now(), raf = 0, visible = false;
  const t0 = last;
  const draw = (now) => {
    const dt = Math.min((now - last) / 1000, 0.05); last = now; const t = (now - t0) / 1000;
    if (beats > 0) { level = Math.min(1, level + 0.28 * beats); for (let i = 0; i < bars; i++) jolt[i] = Math.max(jolt[i], Math.random() ** 2 * (0.6 + 0.4 * level)); beats = 0; }
    level *= Math.exp(-dt * 2.6); for (let i = 0; i < bars; i++) jolt[i] *= Math.exp(-dt * 5);
    const target = on ? 1 : 0;
    energy += (target - energy) * (1 - Math.exp(-dt * (target > energy ? 4 : 2)));
    spin += dt * (0.08 + energy * 0.35);
    if (kick) { wave = 1; waveAt = 0; kick = 0; }
    wave *= Math.exp(-dt * 1.6); waveAt += dt * 2.4;
    ctx.clearRect(0, 0, size, size); ctx.lineCap = "round"; ctx.lineWidth = width;
    const swell = 1 + 0.035 * Math.sin(t * 1.4) * (1 - energy) + 0.05 * energy * (0.5 + 0.5 * Math.sin(t * 4.2)) + wave * 0.07;
    const outline = (ang) => swell * (1 + 0.085 * Math.sin(ang) + (0.025 + 0.02 * energy) * Math.sin(2 * ang + t * 0.7) + (0.018 + 0.015 * energy) * Math.sin(3 * ang - t * 0.5 + 1.1));
    for (let i = 0; i < bars; i++) {
      const a = (i / bars) * Math.PI * 2;
      const shape = 0.5 + 0.28 * Math.sin(a * 3 + t * 1.7) + 0.16 * Math.sin(a * 5 - t * 2.3 + 1.3) + 0.1 * Math.sin(a * 9 + t * 3.1 + 2.1);
      const breathe = 0.12 + 0.06 * Math.sin(t * 1.4);
      const d = Math.abs(((a - waveAt * Math.PI + Math.PI * 3) % (Math.PI * 2)) - Math.PI);
      const bump = wave * Math.exp(-d * d * 3);
      const j = jolt[i] * 0.6 + (jolt[(i + 1) % bars] + jolt[(i + bars - 1) % bars]) * 0.2;
      const h = Math.max(0.04, breathe * (1 - energy) * (1 - level * 0.5) + shape * energy * 0.95 + level * (0.25 + 0.35 * shape) + j * 0.9 + bump * 0.9);
      heights[i] += (h - heights[i]) * (1 - Math.exp(-dt * (h > heights[i] ? 26 : 9)));
      const ang = a + spin - Math.PI / 2, cos = Math.cos(ang), sin = Math.sin(ang), r0 = base * outline(ang), r1 = r0 + heights[i] * reach;
      const x0 = c + cos * r0, y0 = c + sin * r0, x1 = c + cos * r1, y1 = c + sin * r1;
      const g = ctx.createLinearGradient(x0, y0, x1, y1);
      g.addColorStop(0, rgba(0.45 + 0.55 * Math.min(1, heights[i] * 1.4))); g.addColorStop(1, rgba(0));
      ctx.strokeStyle = g; ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
    }
    ctx.beginPath();
    for (let k = 0; k <= 96; k++) { const ang = (k / 96) * Math.PI * 2, r = core * outline(ang); const x = c + Math.cos(ang) * r, y = c + Math.sin(ang) * r; k ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
    ctx.closePath();
    const lit = ctx.createRadialGradient(c - core * 0.35, c - core * 0.45, core * 0.05, c, c, core * 1.15);
    lit.addColorStop(0, rgba(0.26 + 0.1 * energy)); lit.addColorStop(0.55, rgba(0.1 + 0.05 * energy)); lit.addColorStop(1, rgba(0.02));
    ctx.fillStyle = lit; ctx.fill();
    raf = visible && !reduce && !document.hidden ? requestAnimationFrame(draw) : 0;
  };
  const resume = () => { if (!raf && visible && !document.hidden) { last = performance.now(); raf = requestAnimationFrame(draw); } };
  new IntersectionObserver(([e]) => { visible = e.isIntersecting && e.target.offsetParent !== null; resume(); }).observe(el);
  document.addEventListener("visibilitychange", resume);
  if (reduce) { visible = true; draw(performance.now()); }
  return { beat: () => { beats++; }, kick: () => { kick = 1; }, active: (v) => { on = v; }, wake: () => { visible = true; resume(); } };
}

/* ---------- Ask, in the window: a replay of a real chat with kalypso ---------- */
(function askDemo() {
  const panel = $('.panel[data-panel="ask"]');
  if (!panel) return;
  const orb = makeOrb($(".demo-orb"), 112);
  const start = $("#ad-start"), log = $("#ad-log"), text = $("#ad-text"), status = $("#ask-status");
  const ASK = "The login test is flaky on CI and the README is out of date. Can you sort both out?";
  // [kind, text, wait ms after]
  const RUN = [
    ["user", ASK, 900],
    ["text", "Two separate jobs, so I'll run them in parallel: <b>coder</b> takes the flaky test, and a new <b>writer</b> agent updates the README.", 1100],
    ["tool", "kx-agent|list", 600],
    ["tool", "kx-agent|create writer --role \"Keeps the docs accurate\"", 700],
    ["tool", "kx-agent|send coder \"tests/auth/login.test.ts fails 1 in 7 runs…\" --wait 0", 650],
    ["tool", "kx-agent|send writer \"Update the install steps in README.md…\" --wait 0", 650],
    ["tool", "kx-agent|wait coder", 1500],
    ["tool", "kx-agent|wait writer", 1200],
    ["text", "Both are done. <b>coder</b> fixed the flaky test: it checked the URL before the redirect finished, and now 20 of 20 runs pass. <b>writer</b> rewrote the README's install section for Docker and Podman.", 1200],
    ["done", "Done · 9 turns · $0.05", 5200],
  ];
  const esc = (t) => t.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  let timers = [], running = false, inView = false;
  const later = (ms, fn) => timers.push(setTimeout(fn, ms));
  const clear = () => { timers.forEach(clearTimeout); timers = []; };
  const setStatus = (t, done) => { status.lastChild.textContent = t; status.classList.toggle("done", !!done); };
  const add = ([kind, t]) => {
    const li = document.createElement("li");
    li.className = `ad-${kind} new`;
    if (kind === "tool") { const [tool, arg] = t.split("|"); li.innerHTML = `<i>Bash</i><b>${tool}</b> ${esc(arg)}`; }
    else li.innerHTML = kind === "text" ? t : esc(t);
    log.append(li);
    log.scrollTop = log.scrollHeight;
  };
  const play = () => {
    clear(); running = true;
    log.replaceChildren(); text.textContent = ""; start.classList.remove("gone"); setStatus("Ready");
    orb.active(false);
    // Type the request: the orb takes every keystroke.
    let t = 1400;
    for (let k = 1; k <= ASK.length; k++) later((t += 38 + (k % 7 === 0 ? 70 : 0)), () => { text.textContent = ASK.slice(0, k); orb.beat(); });
    // Send: the start screen gives way to the conversation.
    later((t += 500), () => { orb.kick(); orb.active(true); });
    later((t += 700), () => { start.classList.add("gone"); text.textContent = ""; setStatus("Working"); });
    for (const r of RUN) { later((t += 120), () => add(r)); t += r[2]; if (r[0] === "done") later(t - r[2] + 130, () => setStatus("Waiting for a message", true)); }
    later(t, () => { running = false; if (inView && panel.classList.contains("on")) play(); });
  };
  const check = () => {
    const on = inView && panel.classList.contains("on");
    if (on && !running) play();
    if (!on && running) { clear(); running = false; }
  };
  if (reduce) { start.classList.add("gone"); RUN.forEach(add); setStatus("Waiting for a message", true); return; }
  new IntersectionObserver(([e]) => { inView = e.isIntersecting; check(); }, { threshold: 0.35 }).observe(panel.closest(".win"));
  new MutationObserver(check).observe(panel, { attributes: true, attributeFilter: ["class"] });
})();

/* ---------- Layers: assemble on scroll, depth under the cursor ---------- */
(function layersMotion() {
  const isle = $(".isle"), map = $("#isle");
  if (!isle || !map) return;
  const order = ["sandbox", "policies", "vault", "gateway"];
  const plates = order.map((k) => map.querySelector(`[data-layer="${k}"]`)).filter(Boolean);
  plates.forEach((p, k) => p.style.setProperty("--d", k));
  if (reduce) return;
  // Pressed together in the middle until the figure is in view, then spread into the stack.
  // Plates sit ~100 units apart around the middle.
  const mid = (plates.length - 1) / 2;
  const spread = (s) => {
    const k = 1 - s;
    // CSS translations on SVG shapes are in the drawing's own units, so no scaling is needed.
    plates.forEach((p, i) => p.style.setProperty("--gap", `${((i - mid) * 100 * 0.82 * k).toFixed(1)}px`));
    map.style.setProperty("--labels", Math.max(0, (s - 0.55) / 0.45).toFixed(2));
  };
  spread(0);
  const steps = Array.from({ length: 31 }, (_, i) => i / 30);
  new IntersectionObserver(([e]) => spread(Math.min(1, e.intersectionRatio * 1.7)), { threshold: steps }).observe(map);
  // Depth: each plate follows the cursor by a different amount.
  if (matchMedia("(pointer: fine)").matches) {
    isle.addEventListener("pointermove", (e) => {
      const b = isle.getBoundingClientRect();
      map.style.setProperty("--mx", (((e.clientX - b.left) / b.width) * 2 - 1).toFixed(3));
      map.style.setProperty("--my", (((e.clientY - b.top) / b.height) * 2 - 1).toFixed(3));
    });
    isle.addEventListener("pointerleave", () => { map.style.setProperty("--mx", 0); map.style.setProperty("--my", 0); });
  }
})();
